function getReferencedFiles(program: Program, sourceFile: SourceFile, getCanonicalFileName: GetCanonicalFileName): Map<true> | undefined {
    let referencedFiles: Map<true> | undefined;

    // We need to use a set here since the code can contain the same import twice,
    // but that will only be one dependency.
    // To avoid invernal conversion, the key of the referencedFiles map must be of type Path
    if (sourceFile.imports && sourceFile.imports.length > 0) {
        const checker: TypeChecker = program.getTypeChecker();
        for (const importName of sourceFile.imports) {
            const declarationSourceFilePath = getReferencedFileFromImportLiteral(checker, importName);
            if (declarationSourceFilePath) {
                addReferencedFile(declarationSourceFilePath);
            }
        }
    }

    const sourceFileDirectory = getDirectoryPath(sourceFile.path);
    // Handle triple slash references
    if (sourceFile.referencedFiles && sourceFile.referencedFiles.length > 0) {
        for (const referencedFile of sourceFile.referencedFiles) {
            const referencedPath = getReferencedFileFromFileName(program, referencedFile.fileName, sourceFileDirectory, getCanonicalFileName);
            addReferencedFile(referencedPath);
        }
    }

    // Handle type reference directives
    if (sourceFile.resolvedTypeReferenceDirectiveNames) {
        sourceFile.resolvedTypeReferenceDirectiveNames.forEach((resolvedTypeReferenceDirective) => {
            if (!resolvedTypeReferenceDirective) {
                return;
            }

            const fileName = resolvedTypeReferenceDirective.resolvedFileName!; // TODO: GH#18217
            const typeFilePath = getReferencedFileFromFileName(program, fileName, sourceFileDirectory, getCanonicalFileName);
            addReferencedFile(typeFilePath);
        });
    }

    // Add module augmentation as references
    if (sourceFile.moduleAugmentations.length) {
        const checker = program.getTypeChecker();
        for (const moduleName of sourceFile.moduleAugmentations) {
            if (!isStringLiteral(moduleName)) { continue; }
            const symbol = checker.getSymbolAtLocation(moduleName);
            if (!symbol) { continue; }

            // Add any file other than our own as reference
            addReferenceFromAmbientModule(symbol);
        }
    }

    // From ambient modules
    for (const ambientModule of program.getTypeChecker().getAmbientModules()) {
        if (ambientModule.declarations.length > 1) {
            addReferenceFromAmbientModule(ambientModule);
        }
    }

    return referencedFiles;

    function addReferenceFromAmbientModule(symbol: Symbol) {
        // Add any file other than our own as reference
        for (const declaration of symbol.declarations) {
            const declarationSourceFile = getSourceFileOfNode(declaration);
            if (declarationSourceFile &&
                declarationSourceFile !== sourceFile) {
                addReferencedFile(declarationSourceFile.resolvedPath);
            }
        }
    }

    function addReferencedFile(referencedPath: Path) {
        if (!referencedFiles) {
            referencedFiles = createMap<true>();
        }
        referencedFiles.set(referencedPath, true);
    }
}

function getFilesAffectedByUpdatedShapeWhenModuleEmit(state: BuilderState, programOfThisState: Program, sourceFileWithUpdatedShape: SourceFile, cacheToUpdateSignature: Map<string>, cancellationToken: CancellationToken | undefined, computeHash: ComputeHash | undefined, exportedModulesMapCache: ComputingExportedModulesMap | undefined) {
    if (isFileAffectingGlobalScope(sourceFileWithUpdatedShape)) {
        return getAllFilesExcludingDefaultLibraryFile(state, programOfThisState, sourceFileWithUpdatedShape);
    }

    const compilerOptions = programOfThisState.getCompilerOptions();
    if (compilerOptions && (compilerOptions.isolatedModules || compilerOptions.out || compilerOptions.outFile)) {
        return [sourceFileWithUpdatedShape];
    }

    // Now we need to if each file in the referencedBy list has a shape change as well.
    // Because if so, its own referencedBy files need to be saved as well to make the
    // emitting result consistent with files on disk.
    const seenFileNamesMap = createMap<SourceFile>();

    // Start with the paths this file was referenced by
    seenFileNamesMap.set(sourceFileWithUpdatedShape.path, sourceFileWithUpdatedShape);
    const queue = getReferencedByPaths(state, sourceFileWithUpdatedShape.resolvedPath);
    while (queue.length > 0) {
        const currentPath = queue.pop()!;
        if (!seenFileNamesMap.has(currentPath)) {
            const currentSourceFile = programOfThisState.getSourceFileByPath(currentPath)!;
            seenFileNamesMap.set(currentPath, currentSourceFile);
            if (currentSourceFile && updateShapeSignature(state, programOfThisState, currentSourceFile, cacheToUpdateSignature, cancellationToken, computeHash!, exportedModulesMapCache)) { // TODO: GH#18217
                queue.push(...getReferencedByPaths(state, currentSourceFile.resolvedPath));
            }
        }
    }

    // Return array of values that needs emit
    // Return array of values that needs emit
    return arrayFrom(mapDefinedIterator(seenFileNamesMap.values(), value => value));
}

function handleDtsMayChangeOf(state: BuilderProgramState, path: Path, cancellationToken: CancellationToken | undefined, computeHash: BuilderState.ComputeHash) {
    removeSemanticDiagnosticsOf(state, path);

    if (!state.changedFilesSet.has(path)) {
        const program = Debug.assertDefined(state.program);
        const sourceFile = program.getSourceFileByPath(path);
        if (sourceFile) {
            // Even though the js emit doesnt change and we are already handling dts emit and semantic diagnostics
            // we need to update the signature to reflect correctness of the signature(which is output d.ts emit) of this file
            // This ensures that we dont later during incremental builds considering wrong signature.
            // Eg where this also is needed to ensure that .tsbuildinfo generated by incremental build should be same as if it was first fresh build
            BuilderState.updateShapeSignature(
                state,
                program,
                sourceFile,
                Debug.assertDefined(state.currentAffectedFilesSignatures),
                cancellationToken,
                computeHash,
                state.currentAffectedFilesExportedModulesMap
            );
            // If not dts emit, nothing more to do
            if (getEmitDeclarations(state.compilerOptions)) {
                addToAffectedFilesPendingEmit(state, path, BuilderFileEmit.DtsOnly);
            }
        }
    }

    return false;
}

function forEachReferencingModulesOfExportOfAffectedFile(state: BuilderProgramState, affectedFile: SourceFile, fn: (state: BuilderProgramState, filePath: Path) => boolean) {
    // If there was change in signature (dts output) for the changed file,
    // then only we need to handle pending file emit
    if (!state.exportedModulesMap || !state.changedFilesSet.has(affectedFile.path)) {
        return;
    }

    if (!isChangedSignagure(state, affectedFile.path)) return;

    // Since isolated modules dont change js files, files affected by change in signature is itself
    // But we need to cleanup semantic diagnostics and queue dts emit for affected files
    if (state.compilerOptions.isolatedModules) {
        const seenFileNamesMap = createMap<true>();
        seenFileNamesMap.set(affectedFile.path, true);
        const queue = BuilderState.getReferencedByPaths(state, affectedFile.resolvedPath);
        while (queue.length > 0) {
            const currentPath = queue.pop()!;
            if (!seenFileNamesMap.has(currentPath)) {
                seenFileNamesMap.set(currentPath, true);
                const result = fn(state, currentPath);
                if (result && isChangedSignagure(state, currentPath)) {
                    const currentSourceFile = Debug.assertDefined(state.program).getSourceFileByPath(currentPath)!;
                    queue.push(...BuilderState.getReferencedByPaths(state, currentSourceFile.resolvedPath));
                }
            }
        }
    }

    Debug.assert(!!state.currentAffectedFilesExportedModulesMap);
    const seenFileAndExportsOfFile = createMap<true>();
    // Go through exported modules from cache first
    // If exported modules has path, all files referencing file exported from are affected
    if (forEachEntry(state.currentAffectedFilesExportedModulesMap!, (exportedModules, exportedFromPath) =>
        exportedModules &&
        exportedModules.has(affectedFile.path) &&
        forEachFilesReferencingPath(state, exportedFromPath as Path, seenFileAndExportsOfFile, fn)
    )) {
        return;
    }

    // If exported from path is not from cache and exported modules has path, all files referencing file exported from are affected
    forEachEntry(state.exportedModulesMap, (exportedModules, exportedFromPath) =>
        !state.currentAffectedFilesExportedModulesMap!.has(exportedFromPath) && // If we already iterated this through cache, ignore it
        exportedModules.has(affectedFile.path) &&
        forEachFilesReferencingPath(state, exportedFromPath as Path, seenFileAndExportsOfFile, fn)
    );
}

