export function getReferencedByPaths(state: Readonly<BuilderState>, referencedFilePath: Path) {
    return arrayFrom(mapDefinedIterator(state.referencedMap!.entries(), ([filePath, referencesInFile]) =>
        referencesInFile.has(referencedFilePath) ? filePath as Path : undefined
    ));
}

export function updateShapeSignature(state: Readonly<BuilderState>, programOfThisState: Program, sourceFile: SourceFile, cacheToUpdateSignature: Map<string>, cancellationToken: CancellationToken | undefined, computeHash: ComputeHash, exportedModulesMapCache?: ComputingExportedModulesMap) {
    Debug.assert(!!sourceFile);
    Debug.assert(!exportedModulesMapCache || !!state.exportedModulesMap, "Compute visible to outside map only if visibleToOutsideReferencedMap present in the state");

    // If we have cached the result for this file, that means hence forth we should assume file shape is uptodate
    if (state.hasCalledUpdateShapeSignature.has(sourceFile.path) || cacheToUpdateSignature.has(sourceFile.path)) {
        return false;
    }

    const info = state.fileInfos.get(sourceFile.path);
    if (!info) return Debug.fail();

    const prevSignature = info.signature;
    let latestSignature: string;
    if (sourceFile.isDeclarationFile) {
        latestSignature = sourceFile.version;
        if (exportedModulesMapCache && latestSignature !== prevSignature) {
            // All the references in this file are exported
            const references = state.referencedMap ? state.referencedMap.get(sourceFile.path) : undefined;
            exportedModulesMapCache.set(sourceFile.path, references || false);
        }
    }
    else {
        const emitOutput = getFileEmitOutput(
            programOfThisState,
            sourceFile,
            /*emitOnlyDtsFiles*/ true,
            cancellationToken,
            /*customTransformers*/ undefined,
            /*forceDtsEmit*/ true
        );
        const firstDts = emitOutput.outputFiles &&
            programOfThisState.getCompilerOptions().declarationMap ?
            emitOutput.outputFiles.length > 1 ? emitOutput.outputFiles[1] : undefined :
            emitOutput.outputFiles.length > 0 ? emitOutput.outputFiles[0] : undefined;
        if (firstDts) {
            Debug.assert(fileExtensionIs(firstDts.name, Extension.Dts), "File extension for signature expected to be dts", () => `Found: ${getAnyExtensionFromPath(firstDts.name)} for ${firstDts.name}:: All output files: ${JSON.stringify(emitOutput.outputFiles.map(f => f.name))}`);
            latestSignature = computeHash(firstDts.text);
            if (exportedModulesMapCache && latestSignature !== prevSignature) {
                updateExportedModules(sourceFile, emitOutput.exportedModulesFromDeclarationEmit, exportedModulesMapCache);
            }
        }
        else {
            latestSignature = prevSignature!; // TODO: GH#18217
        }

    }
    cacheToUpdateSignature.set(sourceFile.path, latestSignature);

    return !prevSignature || latestSignature !== prevSignature;
}

function getNextAffectedFile(state: BuilderProgramState, cancellationToken: CancellationToken | undefined, computeHash: BuilderState.ComputeHash): SourceFile | Program | undefined {
    while (true) {
        const { affectedFiles } = state;
        if (affectedFiles) {
            const seenAffectedFiles = state.seenAffectedFiles!;
            let affectedFilesIndex = state.affectedFilesIndex!; // TODO: GH#18217
            while (affectedFilesIndex < affectedFiles.length) {
                const affectedFile = affectedFiles[affectedFilesIndex];
                if (!seenAffectedFiles.has(affectedFile.path)) {
                    // Set the next affected file as seen and remove the cached semantic diagnostics
                    state.affectedFilesIndex = affectedFilesIndex;
                    handleDtsMayChangeOfAffectedFile(state, affectedFile, cancellationToken, computeHash);
                    return affectedFile;
                }
                affectedFilesIndex++;
            }

            // Remove the changed file from the change set
            state.changedFilesSet.delete(state.currentChangedFilePath!);
            state.currentChangedFilePath = undefined;
            // Commit the changes in file signature
            BuilderState.updateSignaturesFromCache(state, state.currentAffectedFilesSignatures!);
            state.currentAffectedFilesSignatures!.clear();
            BuilderState.updateExportedFilesMapFromCache(state, state.currentAffectedFilesExportedModulesMap);
            state.affectedFiles = undefined;
        }

        // Get next changed file
        const nextKey = state.changedFilesSet.keys().next();
        if (nextKey.done) {
            // Done
            return undefined;
        }

        // With --out or --outFile all outputs go into single file
        // so operations are performed directly on program, return program
        const program = Debug.assertDefined(state.program);
        const compilerOptions = program.getCompilerOptions();
        if (compilerOptions.outFile || compilerOptions.out) {
            Debug.assert(!state.semanticDiagnosticsPerFile);
            return program;
        }

        // Get next batch of affected files
        state.currentAffectedFilesSignatures = state.currentAffectedFilesSignatures || createMap();
        if (state.exportedModulesMap) {
            state.currentAffectedFilesExportedModulesMap = state.currentAffectedFilesExportedModulesMap || createMap<BuilderState.ReferencedSet | false>();
        }
        state.affectedFiles = BuilderState.getFilesAffectedBy(state, program, nextKey.value as Path, cancellationToken, computeHash, state.currentAffectedFilesSignatures, state.currentAffectedFilesExportedModulesMap);
        state.currentChangedFilePath = nextKey.value as Path;
        state.affectedFilesIndex = 0;
        state.seenAffectedFiles = state.seenAffectedFiles || createMap<true>();
    }
}

function isChangedSignagure(state: BuilderProgramState, path: Path) {
    const newSignature = Debug.assertDefined(state.currentAffectedFilesSignatures).get(path);
    const oldSignagure = Debug.assertDefined(state.fileInfos.get(path)).signature;
    return newSignature !== oldSignagure;
}

function forEachFilesReferencingPath(state: BuilderProgramState, referencedPath: Path, seenFileAndExportsOfFile: Map<true>, fn: (state: BuilderProgramState, filePath: Path) => boolean) {
    return forEachEntry(state.referencedMap!, (referencesInFile, filePath) =>
        referencesInFile.has(referencedPath) && forEachFileAndExportsOfFile(state, filePath as Path, seenFileAndExportsOfFile, fn)
    );
}

export function updateSignaturesFromCache(state: BuilderState, signatureCache: Map<string>) {
    signatureCache.forEach((signature, path) => {
        state.fileInfos.get(path)!.signature = signature;
        state.hasCalledUpdateShapeSignature.set(path, true);
    });
}

function handleDtsMayChangeOf(state: BuilderProgramState, path: Path, cancellationToken: CancellationToken | undefined, computeHash: BuilderState.ComputeHash) {
    removeSemanticDiagnosticsOf(state, path);

    if (!state.changedFilesSet.has(path)) {
        const program = Debug.assertDefined(state.program);
        const sourceFile = program.getSourceFileByPath(path);
        if (sourceFile) {
            // Even though the js emit doesnt change and we are already handling dts emit and semantic diagnostics
            // we need to update the signature to reflect correctness of the signature(which is output d.ts emit) of this file
            // This ensures that we dont later during incremental builds considering wrong signature.
            // Eg where this also is needed to ensure that .tsbuildinfo generated by incremental build should be same as if it was first fresh build
            BuilderState.updateShapeSignature(
                state,
                program,
                sourceFile,
                Debug.assertDefined(state.currentAffectedFilesSignatures),
                cancellationToken,
                computeHash,
                state.currentAffectedFilesExportedModulesMap
            );
            // If not dts emit, nothing more to do
            if (getEmitDeclarations(state.compilerOptions)) {
                addToAffectedFilesPendingEmit(state, path, BuilderFileEmit.DtsOnly);
            }
        }
    }

    return false;
}

function forEachReferencingModulesOfExportOfAffectedFile(state: BuilderProgramState, affectedFile: SourceFile, fn: (state: BuilderProgramState, filePath: Path) => boolean) {
    // If there was change in signature (dts output) for the changed file,
    // then only we need to handle pending file emit
    if (!state.exportedModulesMap || !state.changedFilesSet.has(affectedFile.path)) {
        return;
    }

    if (!isChangedSignagure(state, affectedFile.path)) return;

    // Since isolated modules dont change js files, files affected by change in signature is itself
    // But we need to cleanup semantic diagnostics and queue dts emit for affected files
    if (state.compilerOptions.isolatedModules) {
        const seenFileNamesMap = createMap<true>();
        seenFileNamesMap.set(affectedFile.path, true);
        const queue = BuilderState.getReferencedByPaths(state, affectedFile.resolvedPath);
        while (queue.length > 0) {
            const currentPath = queue.pop()!;
            if (!seenFileNamesMap.has(currentPath)) {
                seenFileNamesMap.set(currentPath, true);
                const result = fn(state, currentPath);
                if (result && isChangedSignagure(state, currentPath)) {
                    const currentSourceFile = Debug.assertDefined(state.program).getSourceFileByPath(currentPath)!;
                    queue.push(...BuilderState.getReferencedByPaths(state, currentSourceFile.resolvedPath));
                }
            }
        }
    }

    Debug.assert(!!state.currentAffectedFilesExportedModulesMap);
    const seenFileAndExportsOfFile = createMap<true>();
    // Go through exported modules from cache first
    // If exported modules has path, all files referencing file exported from are affected
    if (forEachEntry(state.currentAffectedFilesExportedModulesMap!, (exportedModules, exportedFromPath) =>
        exportedModules &&
        exportedModules.has(affectedFile.path) &&
        forEachFilesReferencingPath(state, exportedFromPath as Path, seenFileAndExportsOfFile, fn)
    )) {
        return;
    }

    // If exported from path is not from cache and exported modules has path, all files referencing file exported from are affected
    forEachEntry(state.exportedModulesMap, (exportedModules, exportedFromPath) =>
        !state.currentAffectedFilesExportedModulesMap!.has(exportedFromPath) && // If we already iterated this through cache, ignore it
        exportedModules.has(affectedFile.path) &&
        forEachFilesReferencingPath(state, exportedFromPath as Path, seenFileAndExportsOfFile, fn)
    );
}

export function getFilesAffectedBy(state: BuilderState, programOfThisState: Program, path: Path, cancellationToken: CancellationToken | undefined, computeHash: ComputeHash, cacheToUpdateSignature?: Map<string>, exportedModulesMapCache?: ComputingExportedModulesMap): readonly SourceFile[] {
    // Since the operation could be cancelled, the signatures are always stored in the cache
    // They will be committed once it is safe to use them
    // eg when calling this api from tsserver, if there is no cancellation of the operation
    // In the other cases the affected files signatures are committed only after the iteration through the result is complete
    const signatureCache = cacheToUpdateSignature || createMap();
    const sourceFile = programOfThisState.getSourceFileByPath(path);
    if (!sourceFile) {
        return emptyArray;
    }

    if (!updateShapeSignature(state, programOfThisState, sourceFile, signatureCache, cancellationToken, computeHash, exportedModulesMapCache)) {
        return [sourceFile];
    }

    const result = (state.referencedMap ? getFilesAffectedByUpdatedShapeWhenModuleEmit : getFilesAffectedByUpdatedShapeWhenNonModuleEmit)(state, programOfThisState, sourceFile, signatureCache, cancellationToken, computeHash, exportedModulesMapCache);
    if (!cacheToUpdateSignature) {
        // Commit all the signatures in the signature cache
        updateSignaturesFromCache(state, signatureCache);
    }
    return result;
}
